// NpcConfigServiceClient is the client API for NpcConfigService service.
//
// For semantics around ctx use and closing/ending streaming RPCs, please refer to https://pkg.go.dev/google.golang.org/grpc/?tab=doc#ClientConn.NewStream.
//
// NpcConfigService serves the moderator-editable NPC configuration to tmServer
// (npc-editing-plan.md). It is READ-ONLY from tmServer's side: the web-api writes
// the definitions to Postgres; tmServer polls the version and reloads the full
// snapshot when it changes, then materializes the live entities inside its
// single-owner loop. Separate from AccountService, which mirrors legacy G↔DB.
type NpcConfigServiceClient interface {
	// NpcConfigVersion returns the monotonic config version (cheap poll).
	NpcConfigVersion(ctx context.Context, in *NpcConfigVersionRequest, opts ...grpc.CallOption) (*NpcConfigVersionResponse, error)
	// ListNpcDefinitions returns the full definition snapshot + global price overrides.
	ListNpcDefinitions(ctx context.Context, in *ListNpcDefinitionsRequest, opts ...grpc.CallOption) (*ListNpcDefinitionsResponse, error)
	// ListMobTemplateStats returns every moderator-edited mob/NPC template stat
	// override (mob-template-editing-plan.md, the equivalent-tool successor to
	// the legacy EDITAPPMOB). Deliberately independent of NpcDefinition/
	// ListNpcDefinitions: a stat override applies to ANY npc/<template_name>
	// file (monsters included), not just the DB-managed merchant subset, and
	// is applied by tmServer only once at boot — no version field, because
	// there is no hot-reload for this feature (EDITAPPMOB itself required a
	// server restart too).
	ListMobTemplateStats(ctx context.Context, in *ListMobTemplateStatsRequest, opts ...grpc.CallOption) (*ListMobTemplateStatsResponse, error)
	// ListItemStats returns every moderator-edited item base stat override
	// (0023_item_stats), the item-side sibling of ListMobTemplateStats. Applied
	// by tmServer once at boot for the same reason: these numbers feed the equip
	// score model, which is recomputed per character, so a live swap would leave
	// two players wearing the same item with different stats. Unlike the price
	// overrides in ListNpcDefinitions, which are read at the moment of a shop
	// transaction and hot-reload safely.
	ListItemStats(ctx context.Context, in *ListItemStatsRequest, opts ...grpc.CallOption) (*ListItemStatsResponse, error)
	// ListMountGrowthRates returns the configured mount growth curves
	// (0030_mount_growth_rate): the chance an amago raises an ADULT mount one
	// level, per lineage and per band of twenty levels. Read once at boot like
	// the other content overlays — swapping a curve under a running server would
	// leave two players feeding the same mount at different odds on the same
	// afternoon, and that reads as luck rather than as a change.
	//
	// There is no legacy curve to match: BASE_GetGrowthRate is absent from the
	// sources, so the shape is this server's balance decision.
	ListMountGrowthRates(ctx context.Context, in *ListMountGrowthRatesRequest, opts ...grpc.CallOption) (*ListMountGrowthRatesResponse, error)
	// ListMountAbsorb returns how much of a hit each adult mount eats instead of
	// its owner (0035_mount_absorb), one number against players and one against
	// monsters. Read once at boot, like every other content overlay here.
	//
	// The legacy absorbs a flat 25% either way (_MSG_Attack.cpp:1520-1533). The
	// two numbers are this server's addition: they are what lets a lineage be a
	// PvE mount or a PvP mount rather than one of thirty identical shields. A
	// lineage with no row keeps 25/25 and plays exactly as the original did.
	ListMountAbsorb(ctx context.Context, in *ListMountAbsorbRequest, opts ...grpc.CallOption) (*ListMountAbsorbResponse, error)
	// MountConfigVersion is when the mount overlay last changed, as unix seconds.
	// tmServer reads it beside the tables at boot and reports it back through the
	// control channel, so the panel can tell "saved and live" from "saved, waiting
	// for a restart" — two states that look identical on the screen otherwise.
	MountConfigVersion(ctx context.Context, in *MountConfigVersionRequest, opts ...grpc.CallOption) (*MountConfigVersionResponse, error)
}

